【次の推奨】
提示したGASコードをGoogle Apps Scriptエディタに貼り付け、実際のシート構成（シート名・ヘッダー構造）に合わせてインデックス調整・テスト実行を行ってください。

ご提示いただいた2つのデータ（ぽけてる予約一覧CSV ＆ Lステップ友達詳細CSV）を組み合わせる**「4つ目の機能（突合・マッピング処理）」**のGAS設計案を作成しました。

### 処理の仕組み
1. **ぽけてる予約一覧の絞り込み**：
   - ぽけてる予約データの「ステータス」が**「完了」**の案件をすべて抽出し、顧客名をキーとして保持します。
2. **Lステップ友達詳細データとの突合**：
   - Lステップ友達詳細データの**2〜5列目（表示名、LINE登録名、本名、システム表示名）**のいずれかと、ぽけてるの顧客名が一致するかを照合します。
3. **情報の自動マッピング**：
   - 一致した案件について、ぽけてる側の予約情報と、Lステップ側の**6列目以降の情報**を組み合わせて、指定の出力シートに自動で書き出します。

---

### 実装用 GAS コード設計案

以下のコードを、お使いのGoogleスプレッドシートのGoogle Apps Script（GAS）エディタに追加することで、自動マッピングを実行できます。

```javascript
/**
 * ぽけてるのステータス「完了」案件と、Lステップ友達詳細データを突合・マッピングする関数
 */
function mergePoketeruAndLStep() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. ぽけてる予約一覧シートのデータを取得
  var poketeruSheet = ss.getSheetByName("ぽけてる予約"); // ※実際のシート名に合わせて変更してください
  if (!poketeruSheet) {
    SpreadsheetApp.getUi().alert("「ぽけてる予約」シートが見つかりません。");
    return;
  }
  var poketeruData = poketeruSheet.getDataRange().getValues();
  var pHeaders = poketeruData[0];
  var pNameIdx = pHeaders.indexOf("顧客名");
  var pStatusIdx = pHeaders.indexOf("ステータス");

  if (pNameIdx === -1 || pStatusIdx === -1) {
    SpreadsheetApp.getUi().alert("ぽけてる予約シートに「顧客名」または「ステータス」列が見つかりません。");
    return;
  }

  // ステータス「完了」の案件をマップに格納（名前の前後空白はトリム）
  var completedMap = {};
  for (var i = 1; i < poketeruData.length; i++) {
    var row = poketeruData[i];
    var status = String(row[pStatusIdx]).trim();
    if (status === "完了") {
      var customerName = normalizeName_(row[pNameIdx]);
      if (customerName) {
        completedMap[customerName] = row;
      }
    }
  }

  // 2. Lステップ友達詳細シートのデータを取得
  var lstepSheet = ss.getSheetByName("Lステップ友達詳細"); // ※実際のシート名に合わせて変更してください
  if (!lstepSheet) {
    SpreadsheetApp.getUi().alert("「Lステップ友達詳細」シートが見つかりません。");
    return;
  }
  var lstepData = lstepSheet.getDataRange().getValues();

  var results = [];
  // ヘッダー行を追加（必要に応じて調整）
  // ぽけてるのヘッダー + Lステップの6列目以降のヘッダー
  if (lstepData.length > 0 && poketeruData.length > 0) {
    var lHeaders = lstepData[0].slice(5); // 6列目以降（インデックス5以降）
    results.push(pHeaders.concat(lHeaders));
  }

  // 3. 2〜5列目（インデックス1, 2, 3, 4）で該当案件を探す
  for (var j = 1; j < lstepData.length; j++) {
    var lRow = lstepData[j];
    var candidates = [
      normalizeName_(lRow[1]), // 表示名 (2列目)
      normalizeName_(lRow[2]), // LINE登録名 (3列目)
      normalizeName_(lRow[3]), // 本名 (4列目)
      normalizeName_(lRow[4])  // システム表示名 (5列目)
    ];

    var matched = false;
    for (var k = 0; k < candidates.length; k++) {
      var name = candidates[k];
      if (name && completedMap[name]) {
        var matchedPoketeru = completedMap[name];
        var lstepExtra = lRow.slice(5); // 6列目以降の情報

        // データを結合して追加
        results.push(matchedPoketeru.concat(lstepExtra));
        matched = true;
        break;
      }
    }
  }

  // 4. 結果を「突合結果」シートに出力
  var outputSheet = ss.getSheetByName("突合結果") || ss.insertSheet("突合結果");
  outputSheet.clear();
  if (results.length > 0) {
    outputSheet.getRange(1, 1, results.length, results[0].length).setValues(results);
    SpreadsheetApp.getUi().alert("突合・マッピングが完了しました！合計 " + (results.length - 1) + " 件ヒットしました。");
  } else {
    SpreadsheetApp.getUi().alert("一致する案件はありませんでした。");
  }
}

/**
 * 氏名の表記揺れを防ぐための簡単な正規化ヘルパー
 */
function normalizeName_(str) {
  if (!str) return "";
  return String(str)
    .trim()
    .replace(/\s+/g, "")       // 半角スペース削除
    .replace(/　/g, "")        // 全角スペース削除
    .toLowerCase();
}
```

